//! wasm-bindgen API of the editor engine (`editor/src/engine-pkg`, generated by wasm-bindgen).

use goat_assets::AssetIo;
use goat_gfx_wgpu::{DisplayLayout, WgpuBackend};
use wasm_bindgen::prelude::*;

use crate::core::{entity_of, id_of, EditorCore, TransformEdit};
use crate::tools::GizmoMode;

/// Engine log lines waiting for the editor's Console (`take_logs`).
static LOGS: std::sync::Mutex<Vec<(&'static str, String)>> = std::sync::Mutex::new(Vec::new());

fn log_sink(level: goat_core::log::Level, args: &std::fmt::Arguments<'_>) {
    let text = args.to_string();
    web_sys::console::log_1(&JsValue::from_str(&format!("[{}] {}", level.label(), text)));
    let level = match level {
        goat_core::log::Level::Error => "error",
        goat_core::log::Level::Warn => "warn",
        _ => "info",
    };
    if let Ok(mut l) = LOGS.lock() {
        if l.len() < 1000 {
            l.push((level, text));
        }
    }
}

#[wasm_bindgen]
pub struct EditorEngine {
    gfx: WgpuBackend,
    core: EditorCore,
    width: u32,
    height: u32,
}

#[wasm_bindgen]
impl EditorEngine {
    /// Starts the engine on a canvas (WebGPU, or WebGL2 when unavailable).
    pub async fn create(canvas: web_sys::HtmlCanvasElement) -> Result<EditorEngine, JsValue> {
        console_error_panic_hook::set_once();
        goat_core::log::set_sink(log_sink);
        let (w, h) = (canvas.width().max(1), canvas.height().max(1));
        let gfx = WgpuBackend::new_async(wgpu::SurfaceTarget::Canvas(canvas), w, h, DisplayLayout::Window).await.map_err(|e| JsValue::from_str(&e.to_string()))?;
        let mut core = EditorCore::new(AssetIo::new("assets"));
        core.aspect = w as f32 / h as f32;
        let mut me = EditorEngine { gfx, core, width: w, height: h };
        me.core.first_frame(&mut me.gfx);
        Ok(me)
    }

    /// Engine log lines since the last call: `[[level, text], ...]` (JSON).
    pub fn take_logs(&self) -> String {
        let lines = LOGS.lock().map(|mut l| std::mem::take(&mut *l)).unwrap_or_default();
        serde_json::to_string(&lines).unwrap_or_else(|_| "[]".into())
    }

    pub fn backend_name(&self) -> String {
        goat_gfx::GraphicsBackend::name(&self.gfx).to_string()
    }

    /// Makes a project file available to the engine (the UI reads files through Tauri).
    pub fn put_file(&mut self, key: &str, bytes: Vec<u8>) {
        self.core.io.put(key, bytes);
    }

    pub fn resize(&mut self, width: u32, height: u32) {
        self.width = width.max(1);
        self.height = height.max(1);
        self.gfx.resize(self.width, self.height);
        self.core.aspect = self.width as f32 / self.height as f32;
    }

    pub fn open_scene(&mut self, key: &str) -> Result<(), JsValue> {
        self.core.open_scene(&mut self.gfx, key).map_err(|e| JsValue::from_str(&e))
    }
    pub fn scene(&self) -> Option<String> {
        self.core.scene.clone()
    }
    pub fn save_scene(&mut self) -> Result<String, JsValue> {
        self.core.save_scene().map_err(|e| JsValue::from_str(&e))
    }
    /// JSON array of `{ id, name, parent, kind }`.
    pub fn hierarchy(&self) -> String {
        serde_json::to_string(&self.core.hierarchy()).unwrap_or_default()
    }

    pub fn select(&mut self, id: Option<String>) {
        self.core.select(id.as_deref().and_then(entity_of));
    }
    /// Selects several entities (JSON array of ids; the last is active).
    pub fn select_many(&mut self, ids_json: &str) {
        let ids: Vec<String> = serde_json::from_str(ids_json).unwrap_or_default();
        self.core.select_many(ids.iter().filter_map(|i| entity_of(i)).collect());
    }
    /// JSON array of the selected ids (active last).
    pub fn selection(&self) -> String {
        serde_json::to_string(&self.core.selection.iter().map(|e| id_of(*e)).collect::<Vec<_>>()).unwrap_or_default()
    }

    // ------------------------------------------------------------ undo / clipboard
    /// Call before changing the scene (Undo goes back to this state).
    pub fn record_undo(&mut self, label: &str) {
        self.core.record_undo(label);
    }
    pub fn undo(&mut self) -> Option<String> {
        self.core.undo(&mut self.gfx)
    }
    pub fn redo(&mut self) -> Option<String> {
        self.core.redo(&mut self.gfx)
    }
    pub fn undo_label(&self) -> Option<String> {
        self.core.undo_label().map(str::to_string)
    }
    pub fn redo_label(&self) -> Option<String> {
        self.core.redo_label().map(str::to_string)
    }
    /// The selection as scene JSON (clipboard), or nothing.
    pub fn copy_selection(&mut self) -> Option<String> {
        self.core.copy_selection()
    }
    /// Pastes clipboard JSON under `parent`; returns the new ids (JSON array).
    pub fn paste(&mut self, json: &str, parent: Option<String>) -> Result<String, JsValue> {
        let ids = self.core.paste(&mut self.gfx, json, parent.as_deref().and_then(entity_of)).map_err(|e| JsValue::from_str(&e))?;
        Ok(serde_json::to_string(&ids.into_iter().map(id_of).collect::<Vec<_>>()).unwrap_or_default())
    }
    /// Duplicates the selection; returns the new ids (JSON array).
    pub fn duplicate(&mut self) -> Result<String, JsValue> {
        let ids = self.core.duplicate_selection(&mut self.gfx).map_err(|e| JsValue::from_str(&e))?;
        Ok(serde_json::to_string(&ids.into_iter().map(id_of).collect::<Vec<_>>()).unwrap_or_default())
    }
    /// Runs an Inspector button of a component (e.g. NavMeshSurface ▸ Bake); returns its message.
    pub fn component_action(&mut self, id: &str, component: &str, action: &str) -> Result<String, JsValue> {
        let e = entity_of(id).ok_or_else(|| JsValue::from_str("no entity"))?;
        self.core.component_action(&mut self.gfx, e, component, action).map_err(|e| JsValue::from_str(&e))
    }
    /// `{ components: { name: { menu, defaults?, fields?, requires? } }, behaviours: [...] }`.
    pub fn component_info(&self) -> String {
        self.core.component_info().to_string()
    }
    pub fn selected(&self) -> Option<String> {
        self.core.selected.map(id_of)
    }
    /// Picks at (x, y) in 0..1 of the view; selects and returns the entity id.
    pub fn pick(&mut self, x: f32, y: f32) -> Option<String> {
        let e = self.core.pick(&self.gfx, x, y);
        self.core.select(e);
        e.map(id_of)
    }
    /// `{ position, euler, scale }` of an entity.
    pub fn transform(&self, id: &str) -> Option<String> {
        entity_of(id).and_then(|e| self.core.transform(e)).and_then(|t| serde_json::to_string(&t).ok())
    }
    pub fn set_transform(&mut self, id: &str, json: &str) -> Result<(), JsValue> {
        let t: TransformEdit = serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
        if let Some(e) = entity_of(id) {
            self.core.set_transform(e, &t);
        }
        Ok(())
    }
    pub fn rename(&mut self, id: &str, name: &str) {
        if let Some(e) = entity_of(id) {
            self.core.rename(e, name);
        }
    }

    // ------------------------------------------------------------ components / entities
    /// JSON array of the registered component names.
    pub fn component_names(&self) -> String {
        serde_json::to_string(&self.core.component_names()).unwrap_or_default()
    }
    /// JSON `[{ name, value }]` of an entity's components.
    pub fn components(&mut self, id: &str) -> String {
        entity_of(id).map(|e| self.core.components(e).to_string()).unwrap_or_else(|| "[]".into())
    }
    pub fn set_component(&mut self, id: &str, name: &str, json: &str) -> Result<(), JsValue> {
        let e = entity_of(id).ok_or_else(|| JsValue::from_str("no entity"))?;
        let v: serde_json::Value = serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
        self.core.set_component(&mut self.gfx, e, name, &v).map_err(|e| JsValue::from_str(&e))
    }
    pub fn remove_component(&mut self, id: &str, name: &str) {
        if let Some(e) = entity_of(id) {
            self.core.remove_component(e, name);
        }
    }
    pub fn create_entity(&mut self, name: &str, parent: Option<String>) -> String {
        id_of(self.core.create_entity(name, parent.as_deref().and_then(entity_of)))
    }
    pub fn delete_entity(&mut self, id: &str) {
        if let Some(e) = entity_of(id) {
            self.core.delete_entity(e);
        }
    }
    pub fn set_parent(&mut self, id: &str, parent: Option<String>) {
        if let Some(e) = entity_of(id) {
            self.core.set_parent(e, parent.as_deref().and_then(entity_of));
        }
    }
    /// Drops a model / prefab at a view point (0..1); returns the new entity.
    pub fn instantiate(&mut self, key: &str, x: f32, y: f32) -> Result<String, JsValue> {
        let at = self.core.ground_point(x, y);
        self.core.instantiate(&mut self.gfx, key, at).map(id_of).map_err(|e| JsValue::from_str(&e))
    }

    // ------------------------------------------------------------ gizmos
    /// "move" / "rotate" / "scale".
    pub fn set_gizmo_mode(&mut self, mode: &str) {
        self.core.tools.mode = match mode {
            "rotate" => GizmoMode::Rotate,
            "scale" => GizmoMode::Scale,
            _ => GizmoMode::Move,
        };
    }
    /// Starts a gizmo drag if (x, y) (0..1 of a w × h view) is on a handle.
    pub fn gizmo_begin(&mut self, x: f32, y: f32, w: f32, h: f32) -> bool {
        self.core.tools.dragging = self.core.gizmo_hit(x, y, w, h);
        self.core.tools.dragging.is_some()
    }
    pub fn gizmo_drag(&mut self, dx: f32, dy: f32, w: f32, h: f32) {
        if let Some(axis) = self.core.tools.dragging {
            self.core.gizmo_drag(axis, dx, dy, w, h);
        }
    }
    pub fn gizmo_end(&mut self) {
        self.core.tools.dragging = None;
    }

    pub fn orbit(&mut self, dx: f32, dy: f32) {
        self.core.orbit_by(dx, dy);
    }
    pub fn pan(&mut self, dx: f32, dy: f32) {
        self.core.pan_by(dx, dy);
    }
    pub fn zoom(&mut self, delta: f32) {
        self.core.zoom_by(delta);
    }
    pub fn frame_selected(&mut self) {
        self.core.frame_selected(&self.gfx);
    }

    /// Play mode; `dual_3ds` shows the game as the 3DS's two screens.
    pub fn play(&mut self, dual_3ds: bool) {
        self.gfx.set_layout(if dual_3ds { DisplayLayout::Dual3ds } else { DisplayLayout::Window });
        self.core.play();
    }
    pub fn stop(&mut self) {
        self.core.stop();
        self.gfx.set_layout(DisplayLayout::Window);
    }
    pub fn is_playing(&self) -> bool {
        self.core.is_playing()
    }
    pub fn key(&mut self, code: &str, down: bool) {
        self.core.key(code, down);
    }

    /// One frame (`dt` seconds).
    pub fn frame(&mut self, dt: f32) {
        self.core.frame(&mut self.gfx, dt.min(0.1));
        if !self.core.is_playing() && self.gfx.layout() != DisplayLayout::Window {
            self.gfx.set_layout(DisplayLayout::Window);
        }
    }

    /// Draw calls / triangles of the last frame.
    pub fn stats(&self) -> String {
        let s = if let Some(p) = &self.core.play { p.last_stats } else { self.core.edit.last_stats };
        format!("{} draws · {} tris", s.draw_calls, s.triangles)
    }
}
